window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-afc179cf682c8fff"]={"versions": [{"id": "FIG-afc179cf682c8fff", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der aus vier <code>Data Element</code>-Einträgen zusammengesetzt ist.\n</li><li><strong>Interface1</strong>: Schnittstellenbaustein mit dem Feld <code>Field: A</code>, der über gestrichelte Assoziationslinien mit den beiden P-Ports der Application Software Component und dem R-Port des Diagnostic Manager verknüpft ist.\n</li><li><strong>DiagnosticServiceDataMapping</strong>: Zuordnungselement, das über gerichtete gestrichelte Pfeile auf den oberen P-Port der Softwarekomponente sowie auf den <code>DiagnosticDataIdentifier</code> innerhalb des Diagnostic Manager verweist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Darstellung zeigt eine statische Modellbeziehung und Zuordnungskonfiguration. Über <code>DiagnosticServiceDataMapping</code> wird die Korrelation zwischen dem anwendungsspezifischen Port und dem Diagnose-Identifikator (<code>DiagnosticDataIdentifier</code>) hergestellt. Zur Laufzeit bedient die <code>Application Software Component</code> Anfragen des <code>Diagnostic Manager</code> über die Schnittstelle <code>Interface1</code> (Bereitstellung des Felds <code>Field: A</code>), womit die einzelnen Datenelemente des DIDs bedient werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für den Zugriff des Diagnostic Managers auf Anwendungsdaten das entsprechende Manifest-Mapping (<code>DiagnosticServiceDataMapping</code>) projektieren. Die Schnittstellendefinition erfordert typkonforme Felder (<code>Field: A</code>), die mit den im DID definierten <code>Data Element</code>-Strukturen für Diagnose-Services (z. B. Read/Write Data By Identifier) übereinstimmen.</p>"}, {"id": "FIG-d66049ce241a2369", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der aus vier <code>Data Element</code>-Einträgen zusammengesetzt ist.\n</li><li><strong>Interface1</strong>: Schnittstellenbaustein mit dem Feld <code>Field: A</code>, der über gestrichelte Assoziationslinien mit den beiden P-Ports der Application Software Component und dem R-Port des Diagnostic Manager verknüpft ist.\n</li><li><strong>DiagnosticServiceDataMapping</strong>: Zuordnungselement, das über gerichtete gestrichelte Pfeile auf den oberen P-Port der Softwarekomponente sowie auf den <code>DiagnosticDataIdentifier</code> innerhalb des Diagnostic Manager verweist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Darstellung zeigt eine statische Modellbeziehung und Zuordnungskonfiguration. Über <code>DiagnosticServiceDataMapping</code> wird die Korrelation zwischen dem anwendungsspezifischen Port und dem Diagnose-Identifikator (<code>DiagnosticDataIdentifier</code>) hergestellt. Zur Laufzeit bedient die <code>Application Software Component</code> Anfragen des <code>Diagnostic Manager</code> über die Schnittstelle <code>Interface1</code> (Bereitstellung des Felds <code>Field: A</code>), womit die einzelnen Datenelemente des DIDs bedient werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für den Zugriff des Diagnostic Managers auf Anwendungsdaten das entsprechende Manifest-Mapping (<code>DiagnosticServiceDataMapping</code>) projektieren. Die Schnittstellendefinition erfordert typkonforme Felder (<code>Field: A</code>), die mit den im DID definierten <code>Data Element</code>-Strukturen für Diagnose-Services (z. B. Read/Write Data By Identifier) übereinstimmen.</p>"}, {"id": "FIG-1ff6ebee81a67c90", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der aus vier <code>Data Element</code>-Einträgen zusammengesetzt ist.\n</li><li><strong>Interface1</strong>: Schnittstellenbaustein mit dem Feld <code>Field: A</code>, der über gestrichelte Assoziationslinien mit den beiden P-Ports der Application Software Component und dem R-Port des Diagnostic Manager verknüpft ist.\n</li><li><strong>DiagnosticServiceDataMapping</strong>: Zuordnungselement, das über gerichtete gestrichelte Pfeile auf den oberen P-Port der Softwarekomponente sowie auf den <code>DiagnosticDataIdentifier</code> innerhalb des Diagnostic Manager verweist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Darstellung zeigt eine statische Modellbeziehung und Zuordnungskonfiguration. Über <code>DiagnosticServiceDataMapping</code> wird die Korrelation zwischen dem anwendungsspezifischen Port und dem Diagnose-Identifikator (<code>DiagnosticDataIdentifier</code>) hergestellt. Zur Laufzeit bedient die <code>Application Software Component</code> Anfragen des <code>Diagnostic Manager</code> über die Schnittstelle <code>Interface1</code> (Bereitstellung des Felds <code>Field: A</code>), womit die einzelnen Datenelemente des DIDs bedient werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für den Zugriff des Diagnostic Managers auf Anwendungsdaten das entsprechende Manifest-Mapping (<code>DiagnosticServiceDataMapping</code>) projektieren. Die Schnittstellendefinition erfordert typkonforme Felder (<code>Field: A</code>), die mit den im DID definierten <code>Data Element</code>-Strukturen für Diagnose-Services (z. B. Read/Write Data By Identifier) übereinstimmen.</p>"}, {"id": "FIG-f0bed16a61c51f0f", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der vier dezent/abgeblendet dargestellte <code>Data Element</code>-Segmente enthält.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Spezifische Schnittstellenklasse, die über gestrichelte Linien den P-Ports der Application Software Component sowie dem R-Port des Diagnostic Manager zugeordnet ist.\n</li><li><strong>DiagnosticServiceDataIdentifierPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Application Software Component mit dem <code>DiagnosticDataIdentifier</code> im Diagnostic Manager verknüpft.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Das <code>DiagnosticServiceDataIdentifierPortMapping</code> verknüpft den Provider-Port der Anwendungssoftware mit dem Diagnose-Datenidentifikator im Diagnostic Manager. Die Kommunikation erfolgt normiert über die dedizierte <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle, um die Datenelemente des DIDs für Diagnosedienste bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung erfordert anstelle generischer Schnittstellen die Verwendung des dedizierten Schnittstellentyps <code>DiagnosticDataIdentifierInterface</code>. Zudem muss im Manifest das spezifische <code>DiagnosticServiceDataIdentifierPortMapping</code> instanziiert werden, um den Datenfluss zwischen Service-Port und den Datenelementen des Diagnose-DIDs zu binden.</p>"}, {"id": "FIG-036e80e2c6809048", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der vier dezent/abgeblendet dargestellte <code>Data Element</code>-Segmente enthält.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Spezifische Schnittstellenklasse, die über gestrichelte Linien den P-Ports der Application Software Component sowie dem R-Port des Diagnostic Manager zugeordnet ist.\n</li><li><strong>DiagnosticServiceDataIdentifierPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Application Software Component mit dem <code>DiagnosticDataIdentifier</code> im Diagnostic Manager verknüpft.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Das <code>DiagnosticServiceDataIdentifierPortMapping</code> verknüpft den Provider-Port der Anwendungssoftware mit dem Diagnose-Datenidentifikator im Diagnostic Manager. Die Kommunikation erfolgt normiert über die dedizierte <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle, um die Datenelemente des DIDs für Diagnosedienste bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung erfordert anstelle generischer Schnittstellen die Verwendung des dedizierten Schnittstellentyps <code>DiagnosticDataIdentifierInterface</code>. Zudem muss im Manifest das spezifische <code>DiagnosticServiceDataIdentifierPortMapping</code> instanziiert werden, um den Datenfluss zwischen Service-Port und den Datenelementen des Diagnose-DIDs zu binden.</p>"}, {"id": "FIG-ea82a6406087e5c9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, besitzt einen R-Port (Required Port) und kapselt einen <code>DiagnosticDataIdentifier</code>, der vier dezent/abgeblendet dargestellte <code>Data Element</code>-Segmente enthält.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Spezifische Schnittstellenklasse, die über gestrichelte Linien den P-Ports der Application Software Component sowie dem R-Port des Diagnostic Manager zugeordnet ist.\n</li><li><strong>DiagnosticServiceDataIdentifierPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Application Software Component mit dem <code>DiagnosticDataIdentifier</code> im Diagnostic Manager verknüpft.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Das <code>DiagnosticServiceDataIdentifierPortMapping</code> verknüpft den Provider-Port der Anwendungssoftware mit dem Diagnose-Datenidentifikator im Diagnostic Manager. Die Kommunikation erfolgt normiert über die dedizierte <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle, um die Datenelemente des DIDs für Diagnosedienste bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung erfordert anstelle generischer Schnittstellen die Verwendung des dedizierten Schnittstellentyps <code>DiagnosticDataIdentifierInterface</code>. Zudem muss im Manifest das spezifische <code>DiagnosticServiceDataIdentifierPortMapping</code> instanziiert werden, um den Datenfluss zwischen Service-Port und den Datenelementen des Diagnose-DIDs zu binden.</p>"}, {"id": "FIG-12d02fef72782153", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, kapselt einen <code>DiagnosticDataIdentifier</code> (mit vier abgeblendeten <code>Data Element</code>-Einträgen) und weist einen gestrichelt umrandeten, schraffierten R-Port (Required Port) auf.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Schnittstellendefinition, verknüpft über gestrichelte Linien mit den beiden P-Ports der Application Software Component.\n</li><li><strong>DiagnosticDataPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Anwendungssoftware mit dem <code>DiagnosticDataIdentifier</code> des Diagnostic Manager verbindet. Der R-Port ist horizontal gestrichelt an den <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Über das <code>DiagnosticDataPortMapping</code> wird der P-Port der Application Software Component direkt dem <code>DiagnosticDataIdentifier</code> zugeordnet. Der schraffierte R-Port am Diagnostic Manager verdeutlicht einen optionalen bzw. virtuellen/abstrakten Port-Charakter bei der Anbindung der <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Manifest wird die Vereinheitlichung auf das Meta-Klassen-Konstrukt <code>DiagnosticDataPortMapping</code> umgesetzt. Entwickler müssen beachten, dass der Diagnose-Port am Diagnostic Manager als abgeleitete/optionale Port-Repräsentation (gestrichelt/schraffiert) abgebildet wird, während die Anwendungs-P-Ports über <code>DiagnosticDataPortMapping</code> an die DID-Definition gekoppelt werden.</p>"}, {"id": "FIG-7012ed34673d7498", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, kapselt einen <code>DiagnosticDataIdentifier</code> (mit vier abgeblendeten <code>Data Element</code>-Einträgen) und weist einen gestrichelt umrandeten, schraffierten R-Port (Required Port) auf.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Schnittstellendefinition, verknüpft über gestrichelte Linien mit den beiden P-Ports der Application Software Component.\n</li><li><strong>DiagnosticDataPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Anwendungssoftware mit dem <code>DiagnosticDataIdentifier</code> des Diagnostic Manager verbindet. Der R-Port ist horizontal gestrichelt an den <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Über das <code>DiagnosticDataPortMapping</code> wird der P-Port der Application Software Component direkt dem <code>DiagnosticDataIdentifier</code> zugeordnet. Der schraffierte R-Port am Diagnostic Manager verdeutlicht einen optionalen bzw. virtuellen/abstrakten Port-Charakter bei der Anbindung der <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Manifest wird die Vereinheitlichung auf das Meta-Klassen-Konstrukt <code>DiagnosticDataPortMapping</code> umgesetzt. Entwickler müssen beachten, dass der Diagnose-Port am Diagnostic Manager als abgeleitete/optionale Port-Repräsentation (gestrichelt/schraffiert) abgebildet wird, während die Anwendungs-P-Ports über <code>DiagnosticDataPortMapping</code> an die DID-Definition gekoppelt werden.</p>"}, {"id": "FIG-ea422e72bfe36429", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Manager</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Manager</strong>: Plattform-Komponente zur Diagnoseverwaltung, kapselt einen <code>DiagnosticDataIdentifier</code> (mit vier abgeblendeten <code>Data Element</code>-Einträgen) und weist einen gestrichelt umrandeten, schraffierten R-Port (Required Port) auf.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Schnittstellendefinition, verknüpft über gestrichelte Linien mit den beiden P-Ports der Application Software Component.\n</li><li><strong>DiagnosticDataPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Anwendungssoftware mit dem <code>DiagnosticDataIdentifier</code> des Diagnostic Manager verbindet. Der R-Port ist horizontal gestrichelt an den <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Über das <code>DiagnosticDataPortMapping</code> wird der P-Port der Application Software Component direkt dem <code>DiagnosticDataIdentifier</code> zugeordnet. Der schraffierte R-Port am Diagnostic Manager verdeutlicht einen optionalen bzw. virtuellen/abstrakten Port-Charakter bei der Anbindung der <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Manifest wird die Vereinheitlichung auf das Meta-Klassen-Konstrukt <code>DiagnosticDataPortMapping</code> umgesetzt. Entwickler müssen beachten, dass der Diagnose-Port am Diagnostic Manager als abgeleitete/optionale Port-Repräsentation (gestrichelt/schraffiert) abgebildet wird, während die Anwendungs-P-Ports über <code>DiagnosticDataPortMapping</code> an die DID-Definition gekoppelt werden.</p>"}, {"id": "FIG-2becb2df305a8a8e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Modellierungsdiagramm (Metamodell- / Schnittstellen-Konfigurationsdiagramm) der AUTOSAR Adaptive Platform im Kontext der TPS Manifest Specification. Das Diagramm visualisiert das Zusammenspiel zwischen einer anwendungsseitigen Software-Komponente (<code>Application Software Component</code>) und dem adaptiven Diagnose-Subsystem (<code>Diagnostic Management</code>) für den diagnostischen Datenaustausch via Daten-Identifikatoren (DID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Application Software Component</strong>: Anwendungs-Softwarekomponente mit zwei P-Ports (Provided Ports).\n</li><li><strong>Diagnostic Management</strong>: Plattform-Komponente zur Diagnoseverwaltung, kapselt einen <code>DiagnosticDataIdentifier</code> (mit drei abgeblendeten <code>Data Element</code>-Einträgen) und weist einen gestrichelt umrandeten, hellblau hinterlegten R-Port (Required Port) auf.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Schnittstellendefinition, verknüpft über gepunktete Linien mit den beiden P-Ports der Application Software Component.\n</li><li><strong>DiagnosticDataPortMapping</strong>: Port-Mapping-Element, das über gerichtete gestrichelte Pfeile den oberen P-Port der Anwendungssoftware mit dem <code>DiagnosticDataIdentifier</code> des Diagnostic Management verbindet. Der R-Port ist horizontal gestrichelt an den <code>DiagnosticDataIdentifier</code> angebunden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modell- und Port-Zuordnungskonfiguration für Diagnose-DIDs. Über das <code>DiagnosticDataPortMapping</code> wird der P-Port der Application Software Component direkt dem <code>DiagnosticDataIdentifier</code> zugeordnet. Der gestrichelt umrandete R-Port am Diagnostic Management verdeutlicht einen optionalen bzw. virtuellen/abstrakten Port-Charakter bei der Anbindung der <code>DiagnosticDataIdentifierInterface</code>-Schnittstelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Manifest wird die Vereinheitlichung auf das Meta-Klassen-Konstrukt <code>DiagnosticDataPortMapping</code> umgesetzt. Entwickler müssen beachten, dass der Diagnose-Port am Diagnostic Management als abgeleitete/optionale Port-Repräsentation (gestrichelt) abgebildet wird, während die Anwendungs-P-Ports über <code>DiagnosticDataPortMapping</code> an die DID-Definition gekoppelt werden.</p>"}], "trans": [{"from": "FIG-afc179cf682c8fff", "to": "FIG-d66049ce241a2369", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d66049ce241a2369", "to": "FIG-1ff6ebee81a67c90", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1ff6ebee81a67c90", "to": "FIG-f0bed16a61c51f0f", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstellen-Definition: <code>Interface1</code> mit <code>Field: A</code> ersetzt durch <code>DiagnosticDataIdentifierInterface</code>.\n</li><li>Mapping-Entität: <code>DiagnosticServiceDataMapping</code> umbenannt und typisiert zu <code>DiagnosticServiceDataIdentifierPortMapping</code>.\n</li><li>Ausprägung der Data Elements: Die vier <code>Data Element</code>-Kästchen innerhalb des <code>DiagnosticDataIdentifier</code> sind ausgegraut/abgeblendet dargestellt, was auf eine generische oder abgeleitete Datenstruktur hinweist.\n</li></ul>"}, {"from": "FIG-f0bed16a61c51f0f", "to": "FIG-036e80e2c6809048", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-036e80e2c6809048", "to": "FIG-ea82a6406087e5c9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ea82a6406087e5c9", "to": "FIG-12d02fef72782153", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Mapping-Klasse: <code>DiagnosticServiceDataIdentifierPortMapping</code> umbenannt in <code>DiagnosticDataPortMapping</code>.\n</li><li>R-Port am Diagnostic Manager: Solide Umrandung und Füllung des R-Ports durch eine gestrichelte Umrandung mit Schraffur ersetzt.\n</li><li>Verbindungslinie: Gestrichelte Linie zwischen R-Port und <code>DiagnosticDataIdentifier</code> verläuft nun horizontal statt schräg ansetzend.\n</li></ul>"}, {"from": "FIG-12d02fef72782153", "to": "FIG-7012ed34673d7498", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7012ed34673d7498", "to": "FIG-ea422e72bfe36429", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ea422e72bfe36429", "to": "FIG-2becb2df305a8a8e", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Diagnostic Management</strong>: Komponentenbezeichnung von <code>Diagnostic Manager</code> zu <code>Diagnostic Management</code> geändert.\n</li><li><strong>DiagnosticDataIdentifier</strong>: Anzahl der dargestellten <code>Data Element</code>-Einträge im Kasten von vier auf drei reduziert.\n</li><li><strong>DiagnosticDataIdentifierInterface</strong>: Verbindungslinien von den beiden P-Ports zur Schnittstelle von gestrichelt auf gepunktet geändert.\n</li><li><strong>R-Port</strong>: Schraffur des gestrichelt umrandeten R-Ports durch eine durchgehend hellblaue Füllung ersetzt.\n</li><li><strong>Layout &amp; Typografie</strong>: Textanordnung von <code>Application Software Component</code> auf drei Zeilen umbrochen; kompaktere Gesamtanordnung der Ports und Verbindungslinien.\n</li></ul>"}]};
